/**
 * Calculates the nth number in the Fibonacci sequence.
 *
 * The Fibonacci sequence is a series of numbers where a number is the sum of the two preceding ones, usually starting with 0 and 1.
 *
 * @param {number} n The position of the number in the Fibonacci sequence.
 * @returns {number} The nth number in the Fibonacci sequence.
 * @throws {TypeError} If n is not a positive integer.
 */
function fibonacci(n) {
    // Base case: if n is 0 or 1, return n directly
    if (n <= 1) return n;

    // Recursive case: calculate the nth Fibonacci number as the sum of the two preceding ones
    // This can be optimized for performance using dynamic programming, but the recursive approach is simpler to understand
    return fibonacci(n - 1) + fibonacci(n - 2);
}
